-- Illustrative 3NF design for the same hypothetical business rules.
CREATE TABLE customers (
  customer_id integer PRIMARY KEY,
  customer_name text NOT NULL,
  customer_email text NOT NULL UNIQUE,
  customer_tier text NOT NULL
);

CREATE TABLE categories (
  category_id integer PRIMARY KEY,
  category_name text NOT NULL UNIQUE
);

CREATE TABLE products (
  sku text PRIMARY KEY,
  product_name text NOT NULL,
  category_id integer NOT NULL REFERENCES categories(category_id)
);

CREATE TABLE orders (
  order_id integer PRIMARY KEY,
  order_date date NOT NULL,
  customer_id integer NOT NULL REFERENCES customers(customer_id)
);

CREATE TABLE order_lines (
  order_id integer NOT NULL REFERENCES orders(order_id),
  sku text NOT NULL REFERENCES products(sku),
  quantity integer NOT NULL,
  order_unit_price numeric(10,2) NOT NULL,
  PRIMARY KEY (order_id, sku),
  CHECK (quantity > 0),
  CHECK (order_unit_price >= 0)
);

-- Illustrative PostgreSQL 18-style DDL for a hypothetical retail dataset.
CREATE TABLE sales_channel (
    channel_code text PRIMARY KEY,
    channel_name text NOT NULL
);

CREATE TABLE sales_associate (
    associate_id integer PRIMARY KEY,
    associate_name text NOT NULL
);

CREATE TABLE retail_order (
    order_id integer PRIMARY KEY,
    order_date date NOT NULL,
    channel_code text NOT NULL REFERENCES sales_channel(channel_code),
    associate_id integer NULL REFERENCES sales_associate(associate_id),
    order_total numeric(10,2) NOT NULL CHECK (order_total >= 0)
);

CREATE TABLE fraud_reviewer (
    reviewer_id integer PRIMARY KEY,
    reviewer_name text NOT NULL
);

CREATE TABLE order_fraud_review (
    order_id integer NOT NULL REFERENCES retail_order(order_id),
    reviewer_id integer NOT NULL REFERENCES fraud_reviewer(reviewer_id),
    reviewed_at timestamp NOT NULL,
    decision text NOT NULL CHECK (decision IN ('approve', 'reject', 'escalate')),
    PRIMARY KEY (order_id, reviewer_id, reviewed_at)
);
